func (h *Head) loadChunkSnapshot() (int, int, map[chunks.HeadSeriesRef]*memSeries, error) {
	var (
		dir        string
		snapIdx    int
		snapOffset int
	)
	for {
		var err error
		dir, snapIdx, snapOffset, err = LastChunkSnapshot(h.opts.ChunkDirRoot)
		if err != nil {
			if err == record.ErrNotFound {
				return snapIdx, snapOffset, nil, nil
			}
			return snapIdx, snapOffset, nil, errors.Wrap(err, "find last chunk snapshot")
		}

		if h.wal == nil {
			break
		}

		wlast, _, err := h.wal.LastSegmentAndOffset()
		if err != nil {
			return snapIdx, snapOffset, nil, errors.Wrap(err, "get last WAL segment")
		}
		if snapIdx <= wlast {
			break
		}

		// The snapshot is ahead of the WAL. This can happen if the WAL was
		// truncated or reset after the snapshot was taken, in which case the
		// WAL segment numbering restarted at a lower value. Such a snapshot is
		// stale, so delete it and look for an older, valid one.
		level.Warn(h.logger).Log("msg", "Deleting chunk snapshot that is ahead of the WAL", "dir", dir, "snapshot_index", snapIdx, "wal_index", wlast)
		if err := os.RemoveAll(dir); err != nil {
			return snapIdx, snapOffset, nil, errors.Wrap(err, "delete chunk snapshot ahead of WAL")
		}
	}

	start := time.Now()

